func mcpToolTextWithPlatform(result string, platformSession *platform.Session) *mcplib.CallToolResult {
	if platformSession != nil {
		result = bound.WithMetadata(result, platformSession.OutputMetadata())
	}
	return mcplib.NewToolResultText(result)
}

func mcpToolResultTextWithPlatform(method string, data json.RawMessage, readOnly bool, platformSession *platform.Session) *mcplib.CallToolResult {
	result := bound.EndpointPageResponse(method, data, bound.PageOptions{ReadOnly: readOnly})
	return mcpToolTextWithPlatform(result, platformSession)
}

// mcpToolError keeps provider-controlled typed endpoint errors within the MCP
// text-result budget just like successful endpoint results.
func mcpToolError(message string) *mcplib.CallToolResult {
	return mcplib.NewToolResultError(bound.Text(message))
}

// Reserved transport arguments are accepted on every endpoint tool. They are
// not request fields, so an unused one is ignored instead of copied onto the
// wire. Declared bindings with these names still flow through knownArgs.
func mcpReservedArg(name string) bool {
	switch name {
	case "cursor", "body_json", "body_base64", "content_type":
		return true
	default:
		return false
	}
}

